"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["74952"],{82045(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>h,frontMatter:()=>c,contentTitle:()=>d,toc:()=>p,assets:()=>l});var a=JSON.parse('{"id":"nhcx/v1/api/other/endpoints/other-v1-delete","title":"Support: delete records by correlation ID","description":"Internal troubleshooting operation on the claim service that deletes records by correlationid and action; not part of the business transaction flows.","source":"@site/docs/nhcx/v1/api/other/endpoints/other-v1-delete.mdx","sourceDirName":"nhcx/v1/api/other/endpoints","slug":"/nhcx/v1/api/other/endpoints/other-v1-delete","permalink":"/docs/pr-44/docs/nhcx/v1/api/other/endpoints/other-v1-delete","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Support: delete records by correlation ID","sidebar_label":"Support: delete records by correlation ID","sidebar_class_name":"api-method api-method--post","description":"Internal troubleshooting operation on the claim service that deletes records by correlationid and action; not part of the business transaction flows.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-other.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Patient app: acknowledge a notification subscription","permalink":"/docs/pr-44/docs/nhcx/v1/api/other/endpoints/other-v1-notification-on-subscribe"},"next":{"title":"Recipient: answer a status check","permalink":"/docs/pr-44/docs/nhcx/v1/api/other/endpoints/other-v1-on-status"}}'),o=n(62540),r=n(43023),s=n(85030),i=JSON.parse('{"id":"other_v1_delete","module":"Other","moduleId":"other","kind":"operation","method":"POST","path":"/v1/delete","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Support: delete records by correlation ID","title":"Support: delete records by correlation ID","description":"Internal troubleshooting operation on the claim service that deletes records by correlationid and action; not part of the business transaction flows.\\n\\n### Business purpose\\n\\n`/v1/delete` is a troubleshooting operation on the claim service. It deletes the record identified by a correlation ID and an action, to clear a stuck or erroneous record during integration testing and support. It does not move a claim through its lifecycle.\\n\\n### When to use\\n\\nOnly for troubleshooting, and only when NHCX support asks you to. It is not part of any claim flow.\\n\\n### Preconditions\\n\\n- You have a valid access token.\\n- You know the correlation ID and the action of the record to remove.\\n- NHCX support agrees that deleting it is the right fix.\\n\\n### Postconditions\\n\\nThe record is removed. To carry on, start a new request with a new correlation ID.\\n\\n### Common mistakes\\n\\n- Using it to cancel a pre-authorisation. Cancel with a `Task` on `/v1/task/submit`, workflow `PC01`.\\n- Reusing the old correlation ID after a delete.\\n- Calling it in production without NHCX support.\\n\\n### Best practices\\n\\n- Reserve this call for sandbox troubleshooting and only on NHCX support\'s instruction.\\n- Record the correlation ID, action and reason for every deletion in your own audit log, since the docs describe no NHCX-side confirmation beyond the HTTP status.\\n- Prefer /v1/status to inspect a stuck correlation ID before deleting anything.\\n- Mint a new correlation UUID for any re-submission after a deletion.\\n\\n### Related scenario\\n\\nDuring sandbox testing a hospital\'s integrator submits a claim whose callback keeps failing because their endpoint returned 200 instead of 202. NHCX support asks them to fix the acknowledgement and then clears the stuck record by correlation ID and action using /v1/delete so the test case can be rerun cleanly. The integrator resubmits the claim to /v1/claim/submit under a new correlation UUID, receives a 202, and this time the on_submit callback is acknowledged correctly.\\n\\n### Specification\\n\\nNo chapter of the current documentation covers this operation. It appears only in the claim service\'s OpenAPI.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[],"pathParams":[],"queryParams":[],"body":[{"name":"correlationid","type":"string","required":false,"description":"","encrypted":false},{"name":"action","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"correlationid":"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a","action":"/v1/claim/submit"},"responses":[{"status":"200","description":"The endpoint sits in the claim service, whose domain operations all return 202 Accepted, 400 Request Validation failed, 404 Requested resource was not found and 500 Downstream systems down, each carrying StatusSuccessResponse.","example":{"httpStatus":202,"schema":"StatusSuccessResponse","note":"The claim service spec lists 202, 400, 404 and 500, all carrying StatusSuccessResponse; no worked response body is published for /v1/delete."},"synthesised":false,"fields":[{"name":"httpStatus","type":"integer","required":false,"description":""},{"name":"schema","type":"string","required":false,"description":""},{"name":"note","type":"string","required":false,"description":""}]}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v1/delete \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n  \\"action\\": \\"/v1/claim/submit\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v1/delete \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n  \\"action\\": \\"/v1/claim/submit\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/v1/delete\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n        \\"action\\": \\"/v1/claim/submit\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/v1/delete\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n    \\"action\\": \\"/v1/claim/submit\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/hcx/v1/delete\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n            \\"action\\": \\"/v1/claim/submit\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/hcx/v1/delete\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n        \\"action\\": \\"/v1/claim/submit\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n  \\"action\\": \\"/v1/claim/submit\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/hcx/v1/delete\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/hcx/v1/delete\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n        \\"action\\": \\"/v1/claim/submit\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/hcx/v1/delete\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"correlationid\\": \\"5d4c3b2a-1f0e-4d9c-8b7a-6f5e4d3c2b1a\\",\\n    \\"action\\": \\"/v1/claim/submit\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let c={title:"Support: delete records by correlation ID",sidebar_label:"Support: delete records by correlation ID",sidebar_class_name:"api-method api-method--post",description:"Internal troubleshooting operation on the claim service that deletes records by correlationid and action; not part of the business transaction flows.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-other.yaml",generated:!0},d,l={},p=[];function u(e){return(0,o.jsx)(s.A,{operation:i})}function h(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}}}]);